INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'desert-motors-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Desert Motors in Salmabad.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من محركات الصحراء في Salmabad.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts. Focusing on Full ECU & Suspension Inspection, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات. من خلال خدمة فحص كمبيوتر ونظام التعليق الشامل نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts.</p><p>Focusing on <strong>Full ECU & Suspension Inspection</strong>, our Salmabad specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات.</p><p>من خلال خدمة <strong>فحص كمبيوتر ونظام التعليق الشامل</strong>، يعمل فريقنا في Salmabad على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Desert Motors', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | محركات الصحراء', 'Executive guide by Desert Motors covering Full ECU & Suspension Inspection benchmarks in Bahrain.', 'دليل تنفيذي من محركات الصحراء حول معايير فحص كمبيوتر ونظام التعليق الشامل في البحرين.', 'Sustainability', '{"automotive","sustainability","Salmabad","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
