INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Desert Motors & Service W.L.L.","nameAr":"محركات الصحراء للسيارات والخدمة ذ.م.م","shortEn":"Desert Motors","shortAr":"محركات الصحراء","taglineEn":"4x4 Performance Tuning, Diagnostics & Genuine Parts","taglineAr":"تعديل الدفع الرباعي والفحص الإلكتروني وقطع الغيار الأصلية","aboutEn":"Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts.","aboutAr":"مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات."},"hero":{"titleEn":"Desert Motors — 4x4 Performance Tuning, Diagnostics & Genuine Parts","titleAr":"محركات الصحراء — تعديل الدفع الرباعي والفحص الإلكتروني وقطع الغيار الأصلية","ctaLabelEn":"Explore Desert Motors","ctaLabelAr":"استكشف محركات الصحراء"},"featuredServices":[{"code":"SVC-DIAG","en":"Full ECU & Suspension Inspection","ar":"فحص كمبيوتر ونظام التعليق الشامل","rate":35},{"code":"SVC-CER","en":"5-Year Ceramic Paint Protection","ar":"حماية سيراميك للطلاء 5 سنوات","rate":260},{"code":"AUT-MAJ","en":"10,000km Major Mechanical Overhaul","ar":"الصيانة الدورية الكبرى لكل 10 آلاف كم","rate":145},{"code":"AUT-DIA","en":"OEM Multi-Brand ECU & Hybrid Diagnostics","ar":"فحص الكمبيوتر المتقدم والسيارات الهجينة","rate":28}]}'::jsonb, '{"company":{"nameEn":"Desert Motors & Service W.L.L.","nameAr":"محركات الصحراء للسيارات والخدمة ذ.م.م","shortEn":"Desert Motors","shortAr":"محركات الصحراء","taglineEn":"4x4 Performance Tuning, Diagnostics & Genuine Parts","taglineAr":"تعديل الدفع الرباعي والفحص الإلكتروني وقطع الغيار الأصلية","aboutEn":"Authorized 4x4 service center and spare parts distributor specializing in off-road suspension, ceramic detailing, and OEM parts.","aboutAr":"مركز خدمة معتمد لسيارات الدفع الرباعي وموزع قطع غيار أصلية وتجهيزات الرحلات."},"hero":{"titleEn":"Desert Motors — 4x4 Performance Tuning, Diagnostics & Genuine Parts","title